  ('REBAR', 1, 'Bar diameters and steel grade as per drawing / BBS', 'yes_no', null::numeric, null::numeric, null, false, true),
  ('REBAR', 2, 'Number of bars and spacing as per drawing', 'yes_no', null, null, null, false, true),
